KG_CODE("f:tests/test_driver_actions.py","\"\"\"T2 batch 2c: driver action rungs (click/set_value/type_text by token) and\nthe driver-first observe flip. Fake-driver tests; the delivery policy of\nplan 0.6.3 is asserted call by call.\n\"\"\"\nfrom __future__ import annotations\n\nimport os\nimport unittest\nfrom types import SimpleNamespace\nfrom unittest.mock import patch\n\nfrom autoskill.desktop import actions, uia\nfrom autoskill.desktop import refs\nfrom autoskill.desktop.refs import RefStore\nfrom autoskill.protocol import ErrorCode, ProtocolError\n\n\ndef _token_ref(role=\"textbox\", name=\"Field\", token=\"s00000042:1\", **meta):\n    store = RefStore()\n    store.begin_observation()\n    store.add(None, role=role, name=name, element_token=token,\n              window_pid=100, top_window=77, process=\"app.exe\",\n              window_title=\"App\", **meta)\n    ref = next(iter(store._map))\n    return store, ref\n\n\ndef _ok(effect=\"confirmed\", verified=True, path=\"ax\", evidence=None):\n    \"\"\"Realistic SDK reply. The CUA dispatch seam never publishes `confirmed`\n    without evidence (action_record.rs:570-574 demotes it), so confirmed\n    defaults to a synthesized evidence array; pass evidence=[] explicitly to\n    model the demoted/ack-only shape.\"\"\"\n    if evidence is None and effect == \"confirmed\":\n        evidence = [{\"kind\": \"value_readback\",\n                     \"detail\": \"read back as requested\"}]\n    result = {\"effect\": effect, \"verified\": verified, \"path\": path}\n    if evidence is not None:\n        result[\"evidence\"] = evidence\n    return {\"ok\": True, \"result\": result}\n\n\ndef _err(code, state=\"none\", message=\"no\", wants_fg=None, stale_el=None):\n    \"\"\"Mock an adapter error. Predicate booleans (wants_foreground,\n    stale_element) are set to reasonable defaults for the code so the\n    Python rung behaves as it would with the real adapter.\"\"\"\n    if wants_fg is None:\n        wants_fg = code in (\"background_unavailable\", \"background_occluded\",\n                            \"background_uipi_blocked\")\n    if stale_el is None:\n        stale_el = code in (\"stale_element_token\", \"element_outside_target_window\")\n    return {\"ok\": False, \"error\": {\"code\": code, \"message\": message,\n                                   \"effect_state\": state,\n                                   \"wants_foreground\": wants_fg,\n                                   \"stale_element\": stale_el}}\n\n\ndef _text_ok(text=\"✅ Posted double-click to [1] at screen-point (348, 323).\"):\n    \"\"\"b4c: the dedicated tools' SUCCESS AS TEXT ONLY reply, exactly as the\n    adapter's text_only_action_success synthesizes it from CUA's text\n    (protocol.rs; impl_.rs:7047/:7080/:7100 and :7409/:7441/:7461 at the\n    pin) — effect unverifiable + CUA's text as summary, nothing else.\"\"\"\n    return {\"ok\": True, \"result\": {\"effect\": \"unverifiable\", \"summary\": text}}\n\n\nclass TestClickTokenRung(unittest.TestCase):\n    def setUp(self):\n        env = patch.dict(os.environ, {\"AUTOSKILL_DRIVER\": \"on\"})\n        env.start()\n        self.addCleanup(env.stop)\n\n    def test_verified_click_commits_with_driver_route(self):\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=_ok()) as call:\n            res = actions.click(store, ref)\n        self.assertEqual(res[\"effect_state\"], \"committed\")\n        self.assertTrue(res[\"verified\"])\n        self.assertEqual(res[\"via\"], \"driver-ax\")\n        self.assertEqual(res[\"driver\"][\"delivery\"], \"background\")\n        call.assert_called_once()\n        self.assertEqual(call.call_args[0][0], \"click\")\n\n    def test_ack_only_click_is_honest_unknown(self):\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=_ok(effect=\"unverifiable\", verified=False)):\n            res = actions.click(store, ref)\n        self.assertEqual(res[\"effect_state\"], \"unknown\")\n        self.assertFalse(res[\"verified\"])\n\n    def test_interactive_mode_reissues_foreground_directly(self):\n        # Not in quiet mode: require_interactive passes, one foreground\n        # re-issue, no InteractiveRequired.\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        replies = [_err(\"background_unavailable\"),\n                   _ok(path=\"post_message\")]\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   side_effect=replies) as call:\n            res = actions.click(store, ref)\n        self.assertEqual(res[\"effect_state\"], \"committed\")\n        self.assertEqual(res[\"driver\"][\"delivery\"], \"foreground\")\n        self.assertEqual(call.call_count, 2)\n        self.assertEqual(call.call_args_list[0][0][1][\"delivery_mode\"],\n                         \"background\")\n        self.assertEqual(call.call_args_list[1][0][1][\"delivery_mode\"],\n                         \"foreground\")\n\n    def test_quiet_mode_without_fallback_refuses_no_foreground(self):\n        # DR-02 (owner correction 1): in quiet mode the escalation must\n        # raise InteractiveRequired so deliver() decides; no foreground\n        # re-issue happens here.\n        from autoskill.desktop.actions import BACKGROUND_ONLY\n        from autoskill.protocol import InteractiveRequired\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        token = BACKGROUND_ONLY.set(True)\n        try:\n            with patch(\"autoskill.desktop.driver_backend.try_call\",\n                       return_value=_err(\"background_unavailable\")) as call:\n                with self.assertRaises(InteractiveRequired) as caught:\n                    actions.click(store, ref)\n            self.assertEqual(caught.exception.code, \"background_unavailable\")\n            self.assertEqual(caught.exception.error.effect_state.value, \"none\")\n            self.assertEqual(call.call_count, 1)  # background only\n        finally:\n            BACKGROUND_ONLY.reset(token)\n\n    def test_quiet_mode_with_fallback_reissues_once_via_deliver(self):\n        # The full DR-02 flow: deliver() applies the owner's fallback\n        # setting and annotates delivery/fallback_reason; exactly one\n        # foreground call (the fallback re-run repeats the background\n        # attempt first, like every Python rung).\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        replies = [_err(\"background_unavailable\"),\n                   _err(\"background_unavailable\"),\n                   _ok(path=\"post_message\")]\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   side_effect=replies) as call:\n            res = actions.deliver(lambda: actions.click(store, ref),\n                                  quiet=True, interactive_fallback=True,\n                                  annotate=True)\n        self.assertEqual(res[\"effect_state\"], \"committed\")\n        self.assertEqual(res[\"delivery\"], \"interactive-fallback\")\n        self.assertEqual(res[\"fallback_reason\"][\"code\"],\n                         \"background_unavailable\")\n        fg = [c for c in call.call_args_list\n              if c[0][1][\"delivery_mode\"] == \"foreground\"]\n        self.assertEqual(len(fg), 1)\n\n    def test_uipi_refusal_without_wants_fg_is_final_one_call(self):\n        # Without the foreground escalation marker (wants_fg=False),\n        # uipi_blocked is a final refusal with one background call.\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=_err(\"background_uipi_blocked\",\n                                     wants_fg=False)) as call:\n            with self.assertRaises(ProtocolError) as caught:\n                actions.click(store, ref)\n        self.assertEqual(caught.exception.error.code, ErrorCode.UNSUPPORTED)\n        self.assertEqual(caught.exception.error.effect_state.value, \"none\")\n        self.assertEqual(call.call_count, 1)\n\n    def test_refusal_hint_never_contradicts_its_effect(self):\n        # fx1 (t1 I12): CUA's screenshot_context_missing carries no effect\n        # (snapshot_store.rs:134-139), so the adapter says unknown; the hint\n        # may claim \"before any input\" only when the effect is none.\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        for state, pre_input in ((\"unknown\", False), (\"none\", True)):\n            with self.subTest(state=state):\n                with patch(\"autoskill.desktop.driver_backend.try_call\",\n                           return_value=_err(\"screenshot_context_missing\",\n                                             state=state)):\n                    with self.assertRaises(ProtocolError) as caught:\n                        actions.click(store, ref)\n                error = caught.exception.error\n                self.assertEqual(error.effect_state.value, state)\n                self.assertEqual(\"before any input\" in error.hint, pre_input)\n\n    def test_stale_element_token_maps_to_stale_ref(self):\n        # The stale_element boolean (from CUA's predicate, batch_tools.rs:\n        # 1370-1394) drives the STALE_REF, not a code-string check.\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=_err(\"stale_element_token\", stale_el=True)):\n            with self.assertRaises(ProtocolError) as caught:\n                actions.click(store, ref)\n        self.assertEqual(caught.exception.error.code, ErrorCode.STALE_REF)\n\n    def test_stale_code_without_boolean_is_not_stale(self):\n        # The code alone (without the stale_element boolean) must NOT\n        # trigger STALE_REF - the adapter decides, not the code string.\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=_err(\"stale_element_token\", stale_el=False,\n                                     state=\"none\")):\n            with self.assertRaises(ProtocolError) as caught:\n                actions.click(store, ref)\n        self.assertNotEqual(caught.exception.error.code, ErrorCode.STALE_REF)\n\n    def test_unknown_after_dispatch_is_final_no_replay(self):\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=_err(\"driver_transport_error\",\n                                     state=\"unknown\")) as call:\n            with self.assertRaises(ProtocolError) as caught:\n                actions.click(store, ref)\n        self.assertEqual(caught.exception.error.effect_state.value, \"unknown\")\n        self.assertEqual(call.call_count, 1)\n\n    def test_unavailable_driver_refuses_token_ref_honestly(self):\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=None):\n            with self.assertRaises(ProtocolError) as caught:\n                actions.click(store, ref)\n        self.assertEqual(caught.exception.error.code, ErrorCode.UNSUPPORTED)\n        self.assertIn(\"no input was sent\", caught.exception.error.message)\n\n    def test_double_alone_routes_to_double_click_with_pid(self):\n        # b4c: --double alone uses CUA's dedicated double_click tool: the\n        # wire method changes and pid rides along (the schema requires\n        # it); no double/right/count/button key is sent.\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        text = \"✅ Posted double-click to [1] at screen-point (348, 323).\"\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=_text_ok(text)) as call:\n            res = actions.click(store, ref, double=True)\n        call.assert_called_once()\n        method, params = call.call_args[0]\n        self.assertEqual(method, \"double_click\")\n        self.assertEqual(params, {\"pid\": 100,          # _token_ref's window_pid\n                                  \"element_token\": \"s00000042:1\",\n                                  \"delivery_mode\": \"background\"})\n        # The realistic text-only reply maps through _driver_result:\n        # unverifiable + no evidence -> honest UNKNOWN (K2c), CUA's text\n        # surfaced additively as driver.summary, reply verb still \"click\".\n        self.assertEqual(res[\"effect_state\"], \"unknown\")\n        self.assertFalse(res[\"verified\"])\n        self.assertEqual(res[\"method\"], \"click\")\n        self.assertEqual(res[\"via\"], \"driver-ax\")\n        self.assertEqual(res[\"driver\"][\"effect\"], \"unverifiable\")\n        self.assertEqual(res[\"driver\"][\"summary\"], text)\n        self.assertNotIn(\"evidence\", res[\"driver\"])\n\n    def test_right_alone_routes_to_right_click_with_pid(self):\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        text = \"✅ Shown menu for [1] (screen (348, 323)).\"\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=_text_ok(text)) as call:\n            res = actions.click(store, ref, right=True)\n        call.assert_called_once()\n        method, params = call.call_args[0]\n        self.assertEqual(method, \"right_click\")\n        self.assertEqual(params, {\"pid\": 100,\n                                  \"element_token\": \"s00000042:1\",\n                                  \"delivery_mode\": \"background\"})\n        self.assertEqual(res[\"effect_state\"], \"unknown\")\n        self.assertFalse(res[\"verified\"])\n        self.assertEqual(res[\"driver\"][\"summary\"], text)\n\n    def test_double_with_right_keeps_the_click_remapped_call(self):\n        # --double TOGETHER WITH --right stays click {double, right} — the\n        # remap (count:2 + button:\"right\") is CUA's own click schema; the\n        # dedicated tools have no count/button. Byte-identical to today's\n        # both-flags call, pid ABSENT (regression pin).\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=_ok()) as call:\n            actions.click(store, ref, double=True, right=True)\n        call.assert_called_once()\n        method, params = call.call_args[0]\n        self.assertEqual(method, \"click\")\n        self.assertEqual(params, {\"double\": True, \"right\": True,\n                                  \"element_token\": \"s00000042:1\",\n                                  \"delivery_mode\": \"background\"})\n\n    def test_double_click_reissue_keeps_the_dedicated_method(self):\n        # DR-02 ladder is method-agnostic: the one foreground re-issue\n        # repeats the SAME wire method (double_click), only the delivery\n        # changes (mirrors test_interactive_mode_reissues_foreground_\n        # directly, which pins the click spelling).\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        replies = [_err(\"background_unavailable\"), _text_ok()]\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   side_effect=replies) as call:\n            res = actions.click(store, ref, double=True)\n        self.assertEqual(call.call_count, 2)\n        self.assertEqual([c[0][0] for c in call.call_args_list],\n                         [\"double_click\", \"double_click\"])\n        self.assertEqual(call.call_args_list[0][0][1][\"delivery_mode\"],\n                         \"background\")\n        self.assertEqual(call.call_args_list[1][0][1][\"delivery_mode\"],\n                         \"foreground\")\n        self.assertEqual(res[\"driver\"][\"delivery\"], \"foreground\")\n\n    def test_dedicated_route_still_aims_the_overlay_before_dispatch(self):\n        # b4o/b4of2 pin-before-glide order preserved by the routing change\n        # (connected parts: the aim call must not move or disappear).\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        order = []\n\n        def fake_try_call(method, params, **kw):\n            order.append(\"dispatch\")\n            return _text_ok()\n\n        with patch(\"autoskill.desktop.actions._overlay_aim_rect\",\n                   side_effect=lambda entry: order.append(\"aim\")), \\\n                patch(\"autoskill.desktop.actions._overlay_pulse\"), \\\n                patch(\"autoskill.desktop.driver_backend.try_call\",\n                      side_effect=fake_try_call):\n            actions.click(store, ref, double=True)\n        self.assertEqual(order, [\"aim\", \"dispatch\"])\n\n\nclass TestB5T2UnverifiableNoResend(unittest.TestCase):\n    \"\"\"b5t2 (a): an error the adapter reports as effect_state \"unknown\" —\n    the post-change classification of CUA's pixel-UIA busy shape\n    (impl_.rs:3216-3231: effect:\"unverifiable\" + escalation foreground) —\n    must NEVER trigger the DR-02 foreground re-send, even though\n    wants_foreground is true. The gate actions.py:447 (state == \"none\" and\n    wants_fg) already excludes unknown, so these PIN the Python side (green\n    before and after); the red side of the decision lives in protocol.rs's\n    b5t2 tests. No Python source change.\"\"\"\n\n    def setUp(self):\n        env = patch.dict(os.environ, {\"AUTOSKILL_DRIVER\": \"on\"})\n        env.start()\n        self.addCleanup(env.stop)\n\n    def test_unknown_with_wants_fg_is_final_no_resend(self):\n        # The reply the adapter will build after (a): unknown + wants_fg —\n        # impossible from today's adapter (wants_fg forces none), which is\n        # exactly why this pin matters.\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        msg = ('UIA pixel click busy for pid 100. No fallback input was '\n               'sent. The click effect is unknown; inspect the target '\n               'state before another action. If the provider does not '\n               'recover, retry this action with '\n               'delivery_mode:\"foreground\".')\n        reply = {\"ok\": False, \"error\": {\n            \"code\": \"background_unavailable\",\n            \"message\": msg,\n            \"effect_state\": \"unknown\",\n            \"wants_foreground\": True,\n            \"stale_element\": False}}\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=reply) as call:\n            with self.assertRaises(ProtocolError) as caught:\n                actions.click(store, ref)\n        # ONE background call, no foreground re-send: the click effect is\n        # unknown, a re-send could double the input (the b5t1 review risk).\n        self.assertEqual(call.call_count, 1)\n        self.assertEqual(call.call_args_list[0][0][1][\"delivery_mode\"],\n                         \"background\")\n        # Today's unknown-after-dispatch shape (actions.py:480-486): final\n        # UNSUPPORTED with effect_state unknown, CUA's message preserved.\n        self.assertEqual(caught.exception.error.code, ErrorCode.UNSUPPORTED)\n        self.assertEqual(caught.exception.error.effect_state.value,\n                         \"unknown\")\n        self.assertIn(\"background_unavailable\",\n                      caught.exception.error.message)\n        self.assertIn(\"The click effect is unknown\",\n                      caught.exception.error.message)\n\n    def test_none_with_wants_fg_still_resends_once(self):\n        # Paired DR-02 pin, unchanged by (a): the same error with\n        # effect_state \"none\" (the adapter's answer for the NO-effect\n        # refusals, S1 TASK 3) re-sends exactly once in the foreground.\n        # (Quiet-mode counterpart already pinned by\n        # test_quiet_mode_without_fallback_refuses_no_foreground.)\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        replies = [_err(\"background_unavailable\"), _ok(path=\"post_message\")]\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   side_effect=replies) as call:\n            res = actions.click(store, ref)\n        self.assertEqual(call.call_count, 2)\n        self.assertEqual(call.call_args_list[0][0][1][\"delivery_mode\"],\n                         \"background\")\n        self.assertEqual(call.call_args_list[1][0][1][\"delivery_mode\"],\n                         \"foreground\")\n        self.assertEqual(res[\"driver\"][\"delivery\"], \"foreground\")\n\n\nclass TestSetAndTypeTokenRungs(unittest.TestCase):\n    def setUp(self):\n        env = patch.dict(os.environ, {\"AUTOSKILL_DRIVER\": \"on\"})\n        env.start()\n        self.addCleanup(env.stop)\n\n    def test_set_value_sends_pid_and_value(self):\n        store, ref = _token_ref()\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=_ok()) as call:\n            res = actions.set_value(store, ref, \"alpha\")\n        self.assertEqual(res[\"effect_state\"], \"committed\")\n        params = call.call_args_list[0][0][1]\n        self.assertEqual(params[\"pid\"], 100)\n        self.assertEqual(params[\"value\"], \"alpha\")\n        self.assertEqual(params[\"delivery_mode\"], \"background\")\n\n    def test_type_text_sends_text(self):\n        store, ref = _token_ref()\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=_ok()) as call:\n            res = actions.type_text(store, \"beta\", ref=ref)\n        self.assertEqual(res[\"effect_state\"], \"committed\")\n        self.assertEqual(call.call_args_list[0][0][1][\"text\"], \"beta\")\n\n    def test_python_refs_still_use_the_python_rungs(self):\n        # A control-bearing ref without a token must not touch the driver.\n        class _Value:\n            def __init__(self, initial=\"\"):\n                self._value = initial\n                self.set_calls = []\n                self.IsReadOnly = False\n\n            @property\n            def Value(self):\n                return self._value\n\n            def SetValue(self, v):\n                self.set_calls.append(v)\n                self._value = v\n\n        vp = _Value(\"old\")\n        ctl = SimpleNamespace(ControlTypeName=\"EditControl\", ProcessId=1,\n                              GetValuePattern=lambda: vp)\n        store = RefStore()\n        store.begin_observation()\n        store.add(ctl, role=\"textbox\", name=\"Name\")\n        ref = next(iter(store._map))\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   side_effect=AssertionError(\"driver must not be called\")):\n            res = actions.set_value(store, ref, \"new\")\n        self.assertEqual(res[\"effect_state\"], \"committed\")\n        self.assertEqual(vp.set_calls, [\"new\"])\n\n    def test_real_click_on_token_ref_without_driver_is_refused_not_ignored(self):\n        # b5t3: --real on a driver ref is now CUA's capture-bound pixel click\n        # (tests/test_b5t3_pixel_click.py); with the driver unavailable the\n        # capture cannot be taken, so it is still refused honestly, effect none.\n        store, ref = _token_ref(role=\"button\", name=\"OK\", rect=(10, 10, 50, 30))\n        with patch(\"autoskill.desktop.driver_backend.try_call\", return_value=None):\n            with self.assertRaises(ProtocolError) as caught:\n                actions.click(store, ref, real=True)\n        self.assertEqual(caught.exception.error.code, ErrorCode.UNSUPPORTED)\n        self.assertEqual(caught.exception.error.effect_state.value, \"none\")\n\n    def test_set_value_makes_no_read_after_cuas_reply(self):\n        # fx10 (owner 2026-10-29, \"like CUA\"): CUA's set_value never re-reads\n        # (impl_.rs:6188-6189) - one driver call, CUA's verdict, no `actual`.\n        store, ref = _token_ref()\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   side_effect=[_ok(effect=\"unverifiable\", verified=False)]) as call:\n            res = actions.set_value(store, ref, \"alpha\")\n        self.assertEqual(call.call_count, 1)\n        self.assertEqual(res[\"effect_state\"], \"unknown\")\n        self.assertFalse(res[\"verified\"])\n        self.assertNotIn(\"actual\", res)\n\n    def test_type_makes_no_read_after_cuas_reply(self):\n        # fx10: CUA keeps its PostMessage type unverifiable and tells the\n        # caller to take a fresh snapshot (impl_.rs:5089-5109); no read here.\n        store, ref = _token_ref()\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   side_effect=[_ok(effect=\"unverifiable\", verified=False)]) as call:\n            res = actions.type_text(store, \"beta\", ref=ref)\n        self.assertEqual(call.call_count, 1)\n        self.assertEqual(res[\"effect_state\"], \"unknown\")\n        self.assertNotIn(\"actual\", res)\n\n\nclass TestObserveDriverFirst(unittest.TestCase):\n    def setUp(self):\n        env = patch.dict(os.environ, {\"AUTOSKILL_DRIVER\": \"on\"})\n        env.start()\n        self.addCleanup(env.stop)\n\n    def _window(self):\n        rect = SimpleNamespace(left=0, top=0, right=100, bottom=50)\n        return SimpleNamespace(Name=\"App\", NativeWindowHandle=77,\n                               ProcessId=100, BoundingRectangle=rect)\n\n    def test_driver_reply_builds_token_refs(self):\n        from autoskill import handlers\n        reply = {\"ok\": True, \"result\": {\n            \"elements\": [{\"element_index\": 1, \"element_token\": \"s00000042:1\",\n                          \"role\": \"Edit\", \"label\": \"t1\", \"depth\": 1,\n                          \"frame\": {\"x\": 1, \"y\": 2, \"w\": 3, \"h\": 4}}],\n            \"total_element_count\": 1, \"returned_element_count\": 1,\n            \"snapshot_id\": \"s00000042\"}}\n        session = SimpleNamespace(ref_store=RefStore())\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=reply), \\\n                patch.object(actions, \"_process_name\", return_value=\"app.exe\"), \\\n                patch.object(uia, \"observe\",\n                             side_effect=AssertionError(\"python walk used\")):\n            obs = handlers._observe_via_driver_or_python(\n                self._window(), session, proc=\"app.exe\", title=\"App\",\n                include_offscreen=False, max_nodes=100, max_depth=25)\n        self.assertEqual(obs.ref_count, 1)\n        entry = session.ref_store.resolve(\"@e1\")\n        self.assertEqual(entry.element_token, \"s00000042:1\")\n        self.assertIn('textbox \"t1\"', uia.render(obs))\n\n    def test_unavailable_or_refused_driver_falls_back_to_python(self):\n        from autoskill import handlers\n        session = SimpleNamespace(ref_store=RefStore())\n        fake_obs = uia.Observation(app=\"app.exe\", window_title=\"App\",\n                                   window_rect=None, root=None, ref_count=0,\n                                   node_count=0, truncated=False,\n                                   truncation_reason=None, modal=False,\n                                   elapsed_ms=1)\n        for reply in (None, _err(\"driver_error\")):\n            with self.subTest(reply=reply):\n                with patch(\"autoskill.desktop.driver_backend.try_call\",\n                           return_value=reply), \\\n                        patch.object(uia, \"observe\",\n                                     return_value=fake_obs) as py_walk:\n                    obs = handlers._observe_via_driver_or_python(\n                        self._window(), session, proc=\"app.exe\", title=\"App\",\n                        include_offscreen=False, max_nodes=100, max_depth=25)\n                self.assertIs(obs, fake_obs)\n                py_walk.assert_called_once()\n\n    def test_offscreen_mode_skips_the_driver(self):\n        from autoskill import handlers\n        session = SimpleNamespace(ref_store=RefStore())\n        fake_obs = uia.Observation(app=\"a\", window_title=\"A\",\n                                   window_rect=None, root=None, ref_count=0,\n                                   node_count=0, truncated=False,\n                                   truncation_reason=None, modal=False,\n                                   elapsed_ms=1)\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   side_effect=AssertionError(\"driver must not be called\")), \\\n                patch.object(uia, \"observe\", return_value=fake_obs):\n            obs = handlers._observe_via_driver_or_python(\n                self._window(), session, proc=\"a\", title=\"A\",\n                include_offscreen=True, max_nodes=100, max_depth=25)\n        self.assertIs(obs, fake_obs)\n\n\n\n\n_RAW_SET_VALUE = {\"ok\": True, \"result\": {\n    \"delivery\": {\"mode\": \"unknown\"},\n    \"effect\": \"unverifiable\",\n    \"route\": \"accessibility\",\n    \"summary\": \"\\u2705 Set AXValue on [0] (UIA ValuePattern).\"}}\n\n_RAW_TYPE_TEXT = {\"ok\": True, \"result\": {\n    \"delivery\": {\"mode\": \"background\"},\n    \"effect\": \"confirmed\",\n    \"evidence\": [{\"detail\": \"confirmed\", \"kind\": \"value_readback\"}],\n    \"route\": \"accessibility\",\n    \"summary\": (\"\\u2705 Wrote 2 char(s) on pid 31896 via UIA ValuePattern \"\n                \"(element_index=[0]; verify: confirmed).\")}}\n\n_RAW_CLICK = {\"ok\": True, \"result\": {\n    \"delivery\": {\"mode\": \"background\"},\n    \"effect\": \"unverifiable\",\n    \"route\": \"accessibility\",\n    \"summary\": \"\\u2705 Performed UIA Invoke on [1] (screen (459,336)).\"}}\n\n_ESCALATION_DOC = {\"recommended\": \"foreground\"}  # protocol.rs:762 shape\n\n_NEW_KEYS = (\"route\", \"sdk_delivery\", \"evidence\", \"escalation\", \"summary\")\n# driver-side key -> SDK result source key (only `sdk_delivery` is renamed)\n_SRC_FOR = {\"route\": \"route\", \"sdk_delivery\": \"delivery\", \"evidence\":\n            \"evidence\", \"escalation\": \"escalation\", \"summary\": \"summary\"}\n\n# Goldens captured by running the snippet in the i7 S2 output at pre-edit\n# 3770b54; dict equality is order-insensitive so insertion order is cosmetic.\n# o5 (2026-10-12): every driver result now also carries the observed\n# foreground_changed/cursor_moved booleans; the snapshot class pins them\n# to False with static measurement sources, so the 3770b54 goldens stay\n# the comparison base after unioning the two keys in.\n_GOLDEN_FULL_TYPE_TEXT = {\n    'effect_state': 'committed', 'method': 'type_text', 'via': 'driver-ax',\n    'verified': True,\n    'driver': {'path': 'ax', 'delivery': 'background', 'effect': 'confirmed'}}\n_GOLDEN_PARTIAL_SET_VALUE = {  # fx1: CUA's verdict; fx10: no read, so no `actual`\n    'effect_state': 'unknown', 'method': 'set_value', 'via': 'driver-ax',\n    'verified': False,\n    'driver': {'path': 'ax', 'delivery': 'background',\n               'effect': 'unverifiable'}}\n_GOLDEN_BARE_CLICK = {\n    'effect_state': 'unknown', 'method': 'click', 'via': 'driver-ax',\n    'verified': False,\n    'driver': {'path': 'ax', 'delivery': 'background',\n               'effect': 'unverifiable'}}\n\n\ndef _i7_union_new(golden, fx):\n    \"\"\"Golden 3770b54 result + the new driver keys the fixture carries +\n    the o5 observed-change booleans (False under static sources).\"\"\"\n    adds = {k: fx[s] for k, s in _SRC_FOR.items() if s in fx}\n    return {**golden, \"foreground_changed\": False, \"cursor_moved\": False,\n            \"driver\": {**golden[\"driver\"], **adds}}\n\n\nclass TestI7DriverResultSurface(unittest.TestCase):\n    \"\"\"I7: SDK ActionResult fields surface inside `driver`, additive only.\"\"\"\n\n    def setUp(self):\n        env = patch.dict(os.environ, {\"AUTOSKILL_DRIVER\": \"on\"})\n        env.start()\n        self.addCleanup(env.stop)\n        # o5: the snapshot compares whole dicts; pin the measurement\n        # sources so the observed-change booleans are deterministically\n        # False (a live desktop could flip them mid-test otherwise).\n        for name, constant in ((\"_foreground_handle\", 4242),\n                               (\"_cursor_pos\", (11, 11))):\n            p = patch.object(actions, name, return_value=constant)\n            p.start()\n            self.addCleanup(p.stop)\n\n    @staticmethod\n    def _ws(value=\"alpha\", snapshot=\"s00000043\"):\n        # window_state twin of TestK2cReadback._ws_reply (role \"Edit\"/label\n        # \"Field\" match the default _token_ref textbox \"Field\").\n        return {\"ok\": True, \"result\": {\n            \"elements\": [{\"element_index\": 1,\n                          \"element_token\": f\"{snapshot}:1\",\n                          \"role\": \"Edit\", \"label\": \"Field\", \"depth\": 1,\n                          \"value\": value}],\n            \"total_element_count\": 1, \"returned_element_count\": 1,\n            \"snapshot_id\": snapshot}}\n\n    def test_new_driver_keys_mirror_the_sdk_reply(self):\n        # Full reply: every surfaced key equals the SDK value, copied\n        # unchanged. The raw type_text ActionResult (confirmed + evidence,\n        # so the rung commits with no walk) plus the documented escalation.\n        fx = dict(_RAW_TYPE_TEXT[\"result\"], escalation=_ESCALATION_DOC)\n        store, ref = _token_ref()\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value={\"ok\": True, \"result\": fx}) as call:\n            res = actions.type_text(store, \"be\", ref=ref)\n        self.assertEqual(call.call_count, 1,\n                         \"confirmed+evidence must not walk (K2c intact)\")\n        for key in _NEW_KEYS:\n            self.assertEqual(res[\"driver\"][key], fx[_SRC_FOR[key]], key)\n        # K2c-owned keys are untouched by the addition.\n        self.assertEqual(res[\"driver\"][\"path\"], \"ax\")\n        self.assertEqual(res[\"driver\"][\"delivery\"], \"background\")\n        self.assertEqual(res[\"driver\"][\"effect\"], \"confirmed\")\n        self.assertEqual(res[\"via\"], \"driver-ax\")\n        self.assertTrue(res[\"verified\"])\n        self.assertEqual(res[\"effect_state\"], \"committed\")\n\n        # The raw click ActionResult (no evidence/escalation) mirrors its\n        # three present keys through the click rung.\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=_RAW_CLICK):\n            res = actions.click(store, ref)\n        cf = _RAW_CLICK[\"result\"]\n        for key in (\"route\", \"sdk_delivery\", \"summary\"):\n            self.assertEqual(res[\"driver\"][key], cf[_SRC_FOR[key]], key)\n\n    def test_absent_sdk_keys_are_not_added(self):\n        # set_value's real raw shape has route/delivery/summary but neither\n        # evidence nor escalation: only present keys may appear (fx10: one\n        # call, no read follows).\n        store, ref = _token_ref()\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=_RAW_SET_VALUE):\n            res = actions.set_value(store, ref, \"alpha\")\n        self.assertNotIn(\"evidence\", res[\"driver\"])\n        self.assertNotIn(\"escalation\", res[\"driver\"])\n\n        # A bare effect-only reply adds none of the five keys.\n        bare = {\"ok\": True, \"result\": {\"effect\": \"unverifiable\"}}\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=bare):\n            res = actions.click(store, ref)\n        for key in _NEW_KEYS:\n            self.assertNotIn(key, res[\"driver\"])\n\n    def test_preexisting_keys_unchanged_snapshot(self):\n        # Snapshot against 3770b54's output for the same inputs: the full\n        # and partial cases must equal the golden EXACTLY once the new\n        # keys are unioned into `driver`; the bare case must equal its\n        # golden exactly, unchanged by i7.\n        fx_full = dict(_RAW_TYPE_TEXT[\"result\"], escalation=_ESCALATION_DOC)\n        store, ref = _token_ref()\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value={\"ok\": True, \"result\": fx_full}):\n            res = actions.type_text(store, \"be\", ref=ref)\n        self.assertEqual(res, _i7_union_new(_GOLDEN_FULL_TYPE_TEXT, fx_full))\n\n        store, ref = _token_ref()\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=_RAW_SET_VALUE):\n            res = actions.set_value(store, ref, \"alpha\")\n        self.assertEqual(res, _i7_union_new(_GOLDEN_PARTIAL_SET_VALUE,\n                                            _RAW_SET_VALUE[\"result\"]))\n\n        bare = {\"ok\": True, \"result\": {\"effect\": \"unverifiable\"}}\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=bare):\n            res = actions.click(store, ref)\n        self.assertEqual(res, {**_GOLDEN_BARE_CLICK,\n                         'foreground_changed': False,\n                         'cursor_moved': False})\n\n\n\n\nclass TestO5ForegroundCursorMeasurement(unittest.TestCase):\n    \"\"\"O5: every driver action result reports observed foreground/cursor\n    movement as additive top-level booleans, measured inside _driver_action\n    around its own SDK calls - before the first call, after the final reply,\n    including the DR-02 foreground re-issue (:411-412). Observed change only,\n    never attribution: a human may have moved the mouse meanwhile.\n\n    RESTORE_FOREGROUND is switched off so foreground_returned()'s prev/restore\n    polls do not pollute the counts (measured: +2 reads on a plain click, +4\n    on the deliver flow when left on); with it off, the patched sources see\n    ONLY the O5 measurement reads. The overlay seams are patched so no real\n    pointer motion or dashboard IPC can happen from these tests.\"\"\"\n\n    def setUp(self):\n        env = patch.dict(os.environ, {\"AUTOSKILL_DRIVER\": \"on\"})\n        env.start()\n        self.addCleanup(env.stop)\n        restore = patch.object(actions, \"RESTORE_FOREGROUND\", False)\n        restore.start()\n        self.addCleanup(restore.stop)\n        aim = patch.object(actions, \"_overlay_aim\")\n        aim.start()\n        self.addCleanup(aim.stop)\n        pulse = patch.object(actions, \"_overlay_pulse\")\n        pulse.start()\n        self.addCleanup(pulse.stop)\n\n    def test_background_no_change_reports_false_false(self):\n        # One background attempt, nothing observed moving: both booleans\n        # False, and the measurement happened exactly twice per source -\n        # once before the first SDK call, once after the final reply.\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        fg = patch.object(actions, \"_foreground_handle\",\n                          side_effect=[101, 101])\n        cur = patch.object(actions, \"_cursor_pos\",\n                           side_effect=[(4, 5), (4, 5)], create=True)\n        with fg as fg_mock, cur as cur_mock, \\\n                patch(\"autoskill.desktop.driver_backend.try_call\",\n                      return_value=_ok()) as call:\n            res = actions.click(store, ref)\n        self.assertIs(res[\"foreground_changed\"], False)\n        self.assertIs(res[\"cursor_moved\"], False)\n        self.assertEqual(fg_mock.call_count, 2,\n                         \"one read before the first SDK call, one after the \"\n                         \"final reply\")\n        self.assertEqual(cur_mock.call_count, 2)\n        self.assertEqual(call.call_count, 1)\n        self.assertEqual(res[\"driver\"][\"delivery\"], \"background\")\n\n    def test_foreground_change_reported(self):\n        # Handle 100 -> 200 across the action, cursor pinned: only the\n        # foreground boolean flips.\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        fg = patch.object(actions, \"_foreground_handle\",\n                          side_effect=[100, 200])\n        cur = patch.object(actions, \"_cursor_pos\",\n                           side_effect=[(7, 7), (7, 7)], create=True)\n        with fg as fg_mock, cur as cur_mock, \\\n                patch(\"autoskill.desktop.driver_backend.try_call\",\n                      return_value=_ok()):\n            res = actions.click(store, ref)\n        self.assertIs(res[\"foreground_changed\"], True)\n        self.assertIs(res[\"cursor_moved\"], False)\n        self.assertEqual(fg_mock.call_count, 2)\n        self.assertEqual(cur_mock.call_count, 2)\n\n    def test_cursor_change_reported(self):\n        # Cursor (1,1) -> (2,2) across the action, handle pinned: only the\n        # cursor boolean flips.\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        fg = patch.object(actions, \"_foreground_handle\",\n                          side_effect=[303, 303])\n        cur = patch.object(actions, \"_cursor_pos\",\n                           side_effect=[(1, 1), (2, 2)], create=True)\n        with fg as fg_mock, cur as cur_mock, \\\n                patch(\"autoskill.desktop.driver_backend.try_call\",\n                      return_value=_ok()):\n            res = actions.click(store, ref)\n        self.assertIs(res[\"foreground_changed\"], False)\n        self.assertIs(res[\"cursor_moved\"], True)\n        self.assertEqual(fg_mock.call_count, 2)\n        self.assertEqual(cur_mock.call_count, 2)\n\n    def test_dr02_reissue_measured_across_both_calls(self):\n        # The full DR-02 flow through deliver() (quiet fallback), as in\n        # test_quiet_mode_with_fallback_reissues_once_via_deliver. The\n        # foreground handle flips exactly when the 3rd SDK reply (the\n        # foreground re-issue) has been consumed: sequential side_effect\n        # values cannot prove WHERE a read sits, a call_count-coupled source\n        # can - an after-read taken after the background retry instead of\n        # after the foreground reply would observe 100 and report False.\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        replies = [_err(\"background_unavailable\"),\n                   _err(\"background_unavailable\"),\n                   _ok(path=\"post_message\")]\n\n        def handle():\n            return 500 if call.call_count >= 3 else 100\n\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   side_effect=replies) as call, \\\n                patch.object(actions, \"_foreground_handle\",\n                             side_effect=handle) as fg_mock, \\\n                patch.object(actions, \"_cursor_pos\",\n                             side_effect=[(9, 9)] * 3, create=True) as cur_mock:\n            res = actions.deliver(lambda: actions.click(store, ref),\n                                  quiet=True, interactive_fallback=True,\n                                  annotate=True)\n        self.assertIs(res[\"foreground_changed\"], True)\n        self.assertIs(res[\"cursor_moved\"], False)\n        # deliver() re-runs the action, so _driver_action runs twice: the\n        # quiet attempt reads once before its own SDK call and raises at\n        # require_interactive before any final reply; the interactive re-run\n        # reads before its background retry and after the foreground reply.\n        # 3 reads total per source - the last two bracket the reported result.\n        self.assertEqual(fg_mock.call_count, 3)\n        self.assertEqual(cur_mock.call_count, 3)\n        self.assertEqual(call.call_count, 3)\n        self.assertEqual(call.call_args_list[2][0][1][\"delivery_mode\"],\n                         \"foreground\")\n\n\n\n\nclass TestI6aSinceDelta(unittest.TestCase):\n    \"\"\"i6a: the observe seam asks for deltas (fx10 removed the post-action\n    read); RefStore applies the CUA diff contract. Pure try_call mocks — no\n    daemon, no exe.\"\"\"\n\n    def setUp(self):\n        env = patch.dict(os.environ, {\"AUTOSKILL_DRIVER\": \"on\"})\n        env.start()\n        self.addCleanup(env.stop)\n\n    @staticmethod\n    def _window():\n        rect = SimpleNamespace(left=0, top=0, right=100, bottom=50)\n        return SimpleNamespace(Name=\"App\", NativeWindowHandle=77,\n                               ProcessId=100, BoundingRectangle=rect)\n\n    def _observe(self, store, replies):\n        \"\"\"One observe through the driver-first seam with mocked try_call\n        replies (TestObserveDriverFirst pattern). The patched uia.observe is\n        the python-walk fallback: it must never run on these ok replies.\"\"\"\n        from autoskill import handlers\n        session = SimpleNamespace(ref_store=store)\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   side_effect=replies) as call, \\\n                patch.object(actions, \"_process_name\",\n                             return_value=\"app.exe\"), \\\n                patch.object(uia, \"observe\",\n                             side_effect=AssertionError(\"python walk used\")):\n            obs = handlers._observe_via_driver_or_python(\n                self._window(), session, proc=\"app.exe\", title=\"App\",\n                include_offscreen=False, max_nodes=100, max_depth=25)\n        return obs, call\n\n    @staticmethod\n    def _full_reply():\n        \"\"\"A first full read: 4 rows under snapshot s00000042, minting\n        @e1 Field / @e2 Save / @e3 Cancel / @e4 Note in row order.\"\"\"\n        def row(idx, role, label, **extra):\n            r = {\"element_index\": idx, \"element_token\": f\"s00000042:{idx}\",\n                 \"role\": role, \"label\": label, \"depth\": 1}\n            r.update(extra)\n            return r\n        return {\"ok\": True, \"result\": {\n            \"window_id\": 77, \"pid\": 100, \"snapshot_id\": \"s00000042\",\n            \"elements\": [row(1, \"Edit\", \"Field\", value=\"old\"),\n                         row(2, \"Button\", \"Save\"),\n                         row(3, \"Button\", \"Cancel\"),\n                         row(4, \"Edit\", \"Note\", value=\"hello\")],\n            \"total_element_count\": 4, \"returned_element_count\": 4,\n            \"tree_format\": \"elements\"}}\n\n    @staticmethod\n    def _delta_reply():\n        \"\"\"A since diff reply (window_state_view.rs apply): NEW snapshot\n        s00000043, elements reduced to the added+changed rows, removed row [3]\n        named only in the tree_diff text, header/render shapes verbatim from\n        DiffReport::render.\"\"\"\n        return {\"ok\": True, \"result\": {\n            \"window_id\": 77, \"pid\": 100,\n            \"snapshot_id\": \"s00000043\", \"since\": \"s00000042\",\n            \"since_status\": \"diff\",\n            \"diff_counts\": {\"added\": 1, \"changed\": 1, \"removed\": 1},\n            \"tree_diff\": (\n                \"since s00000042: 1 added, 1 changed, 1 removed. \"\n                \"Use element_tokens s00000043:N for + and ~ rows and unchanged \"\n                \"rows; - ids are from s00000042.\\n\"\n                '+ [5] Button \"Help\"\\n'\n                '~ [1] Edit \"Field\" = \"typed\"\\n'\n                '- [3] Button \"Cancel\"'),\n            \"elements\": [\n                {\"element_index\": 1, \"element_token\": \"s00000043:1\",\n                 \"role\": \"Edit\", \"label\": \"Field\", \"depth\": 1,\n                 \"value\": \"typed\"},\n                {\"element_index\": 5, \"element_token\": \"s00000043:5\",\n                 \"role\": \"Button\", \"label\": \"Help\", \"depth\": 1}],\n            \"total_element_count\": 4, \"returned_element_count\": 4,\n            \"tree_format\": \"elements\"}}\n\n    def test_delta_added_changed_removed_unlisted(self):\n        store = RefStore()\n        self._observe(store, [self._full_reply()])\n        self.assertEqual(store.resolve(\"@e1\").element_token, \"s00000042:1\")\n        self._observe(store, [self._delta_reply()])\n\n        # Changed row [1]: same ref, value and token refreshed in place.\n        changed = store.resolve(\"@e1\")\n        self.assertEqual(changed.name, \"Field\")\n        self.assertEqual(changed.observed_value, \"typed\")\n        self.assertEqual(changed.element_token, \"s00000043:1\")\n\n        # Added row [5]: a NEW ref, resolvable with the new snapshot's token.\n        added = [e for e in store._map.values()\n                 if e.element_token == \"s00000043:5\"]\n        self.assertEqual(len(added), 1)\n        self.assertEqual(added[0].name, \"Help\")\n        self.assertIs(store.resolve(added[0].ref), added[0])\n\n        # Removed row [3]: the ref is retired and refuses to resolve.\n        with self.assertRaises(ProtocolError) as caught:\n            store.resolve(\"@e3\")\n        self.assertIn(caught.exception.error.code,\n                      (ErrorCode.UNKNOWN_REF, ErrorCode.STALE_REF))\n\n        # Unlisted rows keep their identity and stable index; their tokens\n        # move to the NEW snapshot prefix (CUA: \"rows not listed keep their\n        # previous [N]\").\n        unlisted = store.resolve(\"@e2\")\n        self.assertEqual(unlisted.name, \"Save\")\n        self.assertEqual(unlisted.element_token, \"s00000043:2\")\n        note = store.resolve(\"@e4\")\n        self.assertEqual(note.name, \"Note\")\n        self.assertEqual(note.element_token, \"s00000043:4\")\n        self.assertEqual(note.observed_value, \"hello\")\n\n        # 4 live refs: 2 unlisted + 1 changed + 1 added; the removed one is gone.\n        self.assertEqual(len(store), 4)\n\n    def test_fallback_statuses_rebuild_from_the_full_payload(self):\n        # Every non-diff since_status is a full read (window_state_view.rs\n        # fallback_text + SinceOutcome::Fallback constructions); the reply\n        # then carries the complete elements array and the store is rebuilt\n        # exactly as a first observe does — all tokens from the new snapshot.\n        for status in (\"unknown_snapshot\", \"other_window\", \"view_changed\",\n                       \"too_much_changed\", \"diff_too_large\", \"no_snapshot\",\n                       \"no_baseline\"):\n            with self.subTest(status=status):\n                store = RefStore()\n                self._observe(store, [self._full_reply()])\n                fallback = {\"ok\": True, \"result\": {\n                    \"window_id\": 77, \"pid\": 100,\n                    \"snapshot_id\": \"s00000044\", \"since\": \"s00000042\",\n                    \"since_status\": status,\n                    \"elements\": [\n                        {\"element_index\": 1, \"element_token\": \"s00000044:1\",\n                         \"role\": \"Edit\", \"label\": \"Fresh\", \"depth\": 1},\n                        {\"element_index\": 2, \"element_token\": \"s00000044:2\",\n                         \"role\": \"Button\", \"label\": \"Other\", \"depth\": 1}],\n                    \"total_element_count\": 2, \"returned_element_count\": 2,\n                    \"tree_format\": \"elements\"}}\n                self._observe(store, [fallback])\n                self.assertEqual(len(store), 2)\n                self.assertEqual(store.resolve(\"@e1\").name, \"Fresh\")\n                self.assertEqual(store.resolve(\"@e1\").element_token,\n                                 \"s00000044:1\")\n                self.assertEqual(store.resolve(\"@e2\").name, \"Other\")\n                for e in store._map.values():\n                    self.assertTrue(e.element_token.startswith(\"s00000044\"),\n                                    f\"stale token {e.element_token} survived\")\n\n    def test_reindexed_line_rebases_unlisted_indices(self):\n        # CUA render shape (DiffReport::render 1075-1081):\n        # \"reindexed: [first_old-last_old] -> [first_old+delta-last_old+delta]\";\n        # here an inserted row shifts old [2-3] to [3-4]\n        # (window_state_view.rs inserted_row_reports_reindexed_range).\n        store = RefStore()\n        full = {\"ok\": True, \"result\": {\n            \"window_id\": 77, \"pid\": 100, \"snapshot_id\": \"s00000051\",\n            \"elements\": [\n                {\"element_index\": 1, \"element_token\": \"s00000051:1\",\n                 \"role\": \"Edit\", \"label\": \"Name\", \"depth\": 1},\n                {\"element_index\": 2, \"element_token\": \"s00000051:2\",\n                 \"role\": \"Button\", \"label\": \"Save\", \"depth\": 1},\n                {\"element_index\": 3, \"element_token\": \"s00000051:3\",\n                 \"role\": \"Button\", \"label\": \"Cancel\", \"depth\": 1}],\n            \"total_element_count\": 3, \"returned_element_count\": 3,\n            \"tree_format\": \"elements\"}}\n        self._observe(store, [full])\n        delta = {\"ok\": True, \"result\": {\n            \"window_id\": 77, \"pid\": 100,\n            \"snapshot_id\": \"s00000052\", \"since\": \"s00000051\",\n            \"since_status\": \"diff\",\n            \"diff_counts\": {\"added\": 1, \"changed\": 0, \"removed\": 0},\n            \"tree_diff\": (\n                \"since s00000051: 1 added, 0 changed, 0 removed. \"\n                \"Use element_tokens s00000052:N for + and ~ rows and unchanged \"\n                \"rows; - ids are from s00000051.\\n\"\n                '+ [2] CheckBox \"New\"\\n'\n                \"reindexed: [2-3] -> [3-4]\"),\n            \"elements\": [\n                {\"element_index\": 2, \"element_token\": \"s00000052:2\",\n                 \"role\": \"CheckBox\", \"label\": \"New\", \"depth\": 1}],\n            \"total_element_count\": 4, \"returned_element_count\": 4,\n            \"tree_format\": \"elements\"}}\n        self._observe(store, [delta])\n        # Unlisted rows outside the range keep their index; inside it they\n        # are re-based by the delta.\n        self.assertEqual(store.resolve(\"@e1\").element_token, \"s00000052:1\")\n        self.assertEqual(store.resolve(\"@e1\").name, \"Name\")\n        save = store.resolve(\"@e2\")\n        self.assertEqual(save.name, \"Save\")\n        self.assertEqual(save.element_token, \"s00000052:3\")\n        cancel = store.resolve(\"@e3\")\n        self.assertEqual(cancel.name, \"Cancel\")\n        self.assertEqual(cancel.element_token, \"s00000052:4\")\n        # The added row is addressable at its new index.\n        added = [e for e in store._map.values()\n                 if e.element_token == \"s00000052:2\"]\n        self.assertEqual(len(added), 1)\n        self.assertEqual(added[0].name, \"New\")\n\n    def test_first_observe_sends_no_since(self):\n        # The first observe of a window is a full read: no since key at all.\n        store = RefStore()\n        _, call = self._observe(store, [self._full_reply()])\n        self.assertEqual(call.call_count, 1)\n        self.assertEqual(call.call_args_list[0][0][0], \"window_state\")\n        self.assertEqual(call.call_args_list[0][0][1],\n                         {\"pid\": 100, \"window_id\": 77,\n                          \"max_elements\": 100, \"max_depth\": 25})\n\n    def test_reobserve_of_observed_window_sends_since_latest(self):\n        # A re-observe while the window's refs are live asks for the delta:\n        # exactly the same params plus since:\"latest\", still one call.\n        # i6a-off: only with DRIVER_SINCE_READS True (the default False\n        # sends no since - the pinned SDK errors its own delta output).\n        _p = patch.object(refs, \"DRIVER_SINCE_READS\", True)\n        _p.start()\n        self.addCleanup(_p.stop)\n        store = RefStore()\n        self._observe(store, [self._full_reply()])\n        _, call = self._observe(store, [self._delta_reply()])\n        self.assertEqual(call.call_count, 1)\n        self.assertEqual(call.call_args_list[0][0][1],\n                         {\"pid\": 100, \"window_id\": 77,\n                          \"max_elements\": 100, \"max_depth\": 25,\n                          \"since\": \"latest\"})\n\n\n\n\nclass TestI6aOffSwitch(unittest.TestCase):\n    \"\"\"i6a-off batch: DRIVER_SINCE_READS (desktop/refs.py) defaults False, so\n    the send site (handlers re-observe; fx10 removed the post-action read) omits\n    the \"since\" key — the exact ca298bf wire shape; patched True, the dormant\n    i6a behavior wakes again. Pure try_call mocks — no daemon, no exe.\"\"\"\n\n    def setUp(self):\n        env = patch.dict(os.environ, {\"AUTOSKILL_DRIVER\": \"on\"})\n        env.start()\n        self.addCleanup(env.stop)\n\n    # Reuse TestI6aSinceDelta's driver-first observe seam helpers verbatim\n    # (_observe calls self._window() and reads self._full_reply()).\n    _observe = TestI6aSinceDelta._observe\n    _window = staticmethod(TestI6aSinceDelta._window)\n    _full_reply = staticmethod(TestI6aSinceDelta._full_reply)\n    _delta_reply = staticmethod(TestI6aSinceDelta._delta_reply)\n\n    def test_switch_off_reobserve_sends_no_since(self):\n        # Default (unpatched) switch: a re-observe of a live window sends the\n        # exact ca298bf full-read params — no \"since\" key at all.\n        self.assertIs(refs.DRIVER_SINCE_READS, False,\n                      \"DRIVER_SINCE_READS must exist and default to False\")\n        store = RefStore()\n        self._observe(store, [self._full_reply()])\n        _, call = self._observe(store, [self._full_reply()])\n        self.assertEqual(call.call_count, 1)\n        self.assertEqual(call.call_args_list[0][0][0], \"window_state\")\n        params = call.call_args_list[0][0][1]\n        self.assertEqual(params,\n                         {\"pid\": 100, \"window_id\": 77,\n                          \"max_elements\": 100, \"max_depth\": 25})\n        self.assertNotIn(\"since\", params)\n\n    def test_switch_true_restores_since_sends(self):\n        # Dormancy pin: patched True, the re-observe sends since:\"latest\"\n        # again — the switch hides i6a, it does not delete it.\n        with patch.object(refs, \"DRIVER_SINCE_READS\", True):\n            store = RefStore()\n            self._observe(store, [self._full_reply()])\n            _, call = self._observe(store, [self._delta_reply()])\n            self.assertEqual(call.call_args_list[0][0][1],\n                             {\"pid\": 100, \"window_id\": 77,\n                              \"max_elements\": 100, \"max_depth\": 25,\n                              \"since\": \"latest\"})\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n\n\nclass TestCorrectionBatch2(unittest.TestCase):\n    def setUp(self):\n        env = patch.dict(os.environ, {\"AUTOSKILL_DRIVER\": \"on\"})\n        env.start()\n        self.addCleanup(env.stop)\n\n    @staticmethod\n    def _two_field_store():\n        from autoskill.desktop import uia as uiam\n        store = RefStore()\n        store.begin_observation()\n        store.add(None, role=\"textbox\", name=\"A\", element_token=\"s00000042:1\",\n                  window_pid=100, top_window=77, rect=(10, 10, 110, 30),\n                  observed_value=\"\")\n        store.add(None, role=\"textbox\", name=\"B\", element_token=\"s00000042:2\",\n                  window_pid=100, top_window=77, rect=(10, 40, 110, 60),\n                  observed_value=\"\")\n        return store\n\n    def test_two_set_values_from_one_observation(self):\n        # Owner correction 1: sibling refs must stay usable. fx10: no read\n        # follows a set_value, so no new snapshot is published and both\n        # tokens of the one observation stay valid as they were.\n        store = self._two_field_store()\n        a1, a2 = \"@e1\", \"@e2\"\n        ack = _ok(effect=\"unverifiable\", verified=False)\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   side_effect=[ack, _ok(evidence=[])]) as call:\n            r1 = actions.set_value(store, a1, \"one\")\n            r2 = actions.set_value(store, a2, \"two\")\n        self.assertEqual(call.call_count, 2)\n        self.assertEqual([c[0][0] for c in call.call_args_list], [\"set_value\", \"set_value\"])\n        self.assertEqual(r1[\"effect_state\"], \"unknown\")\n        self.assertEqual(r2[\"effect_state\"], \"unknown\")\n        self.assertEqual(store.resolve(a1).element_token, \"s00000042:1\")\n        self.assertEqual(store.resolve(a2).element_token, \"s00000042:2\")\n\n    def test_type_with_unverifiable_reply_stays_unknown(self):\n        store = self._two_field_store()\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   side_effect=[_ok(effect=\"unverifiable\", verified=False)]):\n            res = actions.type_text(store, \"beta\", ref=\"@e1\")\n        self.assertEqual(res[\"effect_state\"], \"unknown\")\n\n    def test_driver_refs_aim_and_pulse_the_overlay(self):\n        store = self._two_field_store()\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   side_effect=[_ok()]), \\\n                patch(\"autoskill.desktop.actions._overlay_aim\") as aim, \\\n                patch(\"autoskill.desktop.actions.overlay\") as ov:\n            actions.set_value(store, \"@e1\", \"x\")\n        aim.assert_called_once_with(60, 20)  # centre of the (10,10,110,30) rect\n        self.assertTrue(ov.pulse.called)\n        self.assertEqual(ov.say.call_args_list[0][0][1], \"aiming\")\n\n\nclass TestK4aRegression(unittest.TestCase):\n    \"\"\"K4a: DR-02 must still re-issue on background_unavailable that carries\n    NO refused markers (the delivery.rs builder omits them; the adapter's\n    wants_foreground predicate supplies effect none).\"\"\"\n\n    def setUp(self):\n        env = patch.dict(os.environ, {\"AUTOSKILL_DRIVER\": \"on\"})\n        env.start()\n        self.addCleanup(env.stop)\n\n    def test_dr02_reissues_without_refused_markers(self):\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        # The exact delivery.rs shape: code + escalation.recommended, NO\n        # status/effect \"refused\" (cua-driver-core/src/delivery.rs:62-83).\n        # The adapter's wants_foreground predicate fires on the escalation\n        # marker and sends wants_foreground: true to Python.\n        bg_no_refused = {\n            \"ok\": False,\n            \"error\": {\n                \"code\": \"background_unavailable\",\n                \"message\": 'Background delivery is not available. '\n                           'Retry this action with delivery_mode:\"foreground\"',\n                \"effect_state\": \"none\",\n                \"wants_foreground\": True,\n                \"stale_element\": False,\n            },\n        }\n        replies = [bg_no_refused, bg_no_refused, _ok(path=\"post_message\")]\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   side_effect=replies) as call:\n            res = actions.deliver(lambda: actions.click(store, ref),\n                                  quiet=True, interactive_fallback=True,\n                                  annotate=True)\n        self.assertEqual(res[\"effect_state\"], \"committed\")\n        self.assertEqual(res[\"delivery\"], \"interactive-fallback\")\n        self.assertEqual(res[\"fallback_reason\"][\"code\"], \"background_unavailable\")\n        fg = [c for c in call.call_args_list\n              if c[0][1][\"delivery_mode\"] == \"foreground\"]\n        self.assertEqual(len(fg), 1)\n\n    def test_dr02_no_reissue_when_not_opted_in(self):\n        from autoskill.desktop.actions import BACKGROUND_ONLY\n        from autoskill.protocol import InteractiveRequired\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        bg = _err(\"background_unavailable\")\n        token = BACKGROUND_ONLY.set(True)\n        try:\n            with patch(\"autoskill.desktop.driver_backend.try_call\",\n                       return_value=bg) as call:\n                with self.assertRaises(InteractiveRequired):\n                    actions.click(store, ref)\n            self.assertEqual(call.call_count, 1)\n            self.assertEqual(call.call_args_list[0][0][1][\"delivery_mode\"],\n                             \"background\")\n        finally:\n            BACKGROUND_ONLY.reset(token)\n\n    def test_stale_element_outside_window_maps_to_stale_ref(self):\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=_err(\"element_outside_target_window\")):\n            with self.assertRaises(ProtocolError) as caught:\n                actions.click(store, ref)\n        self.assertEqual(caught.exception.error.code, ErrorCode.STALE_REF)\n\n\nclass TestK4aFix(unittest.TestCase):\n    \"\"\"K4a-fix D3/D4: DR-02 triggers on wants_foreground (not a code list);\n    stale raises on the stale_element boolean (not code-string checks).\"\"\"\n\n    def setUp(self):\n        env = patch.dict(os.environ, {\"AUTOSKILL_DRIVER\": \"on\"})\n        env.start()\n        self.addCleanup(env.stop)\n\n    @staticmethod\n    def _err_w_predicates(code, effect=\"none\", wants_fg=False, stale_el=False,\n                           message=\"refused\"):\n        return {\"ok\": False, \"error\": {\n            \"code\": code, \"message\": message, \"effect_state\": effect,\n            \"wants_foreground\": wants_fg, \"stale_element\": stale_el}}\n\n    def test_dr02_reissues_on_uipi_blocked_with_wants_foreground(self):\n        # D3: background_uipi_blocked + escalation.recommended \"foreground\"\n        # must trigger the re-issue (the old code list would have missed it).\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        bg_uipi = self._err_w_predicates(\"background_uipi_blocked\",\n                                         wants_fg=True,\n                                         message='Background delivery is not available. '\n                                                 'Retry this action with delivery_mode:\"foreground\"')\n        replies = [bg_uipi, bg_uipi, _ok(path=\"post_message\")]\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   side_effect=replies) as call:\n            res = actions.deliver(lambda: actions.click(store, ref),\n                                  quiet=True, interactive_fallback=True,\n                                  annotate=True)\n        self.assertEqual(res[\"effect_state\"], \"committed\")\n        self.assertEqual(res[\"delivery\"], \"interactive-fallback\")\n        self.assertEqual(res[\"fallback_reason\"][\"code\"], \"background_uipi_blocked\")\n        fg = [c for c in call.call_args_list\n              if c[0][1][\"delivery_mode\"] == \"foreground\"]\n        self.assertEqual(len(fg), 1)\n\n    def test_dr02_no_reissue_without_opt_in(self):\n        from autoskill.desktop.actions import BACKGROUND_ONLY\n        from autoskill.protocol import InteractiveRequired\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        bg = self._err_w_predicates(\"background_uipi_blocked\", wants_fg=True)\n        token = BACKGROUND_ONLY.set(True)\n        try:\n            with patch(\"autoskill.desktop.driver_backend.try_call\",\n                       return_value=bg) as call:\n                with self.assertRaises(InteractiveRequired):\n                    actions.click(store, ref)\n            self.assertEqual(call.call_count, 1)\n            self.assertEqual(call.call_args_list[0][0][1][\"delivery_mode\"],\n                             \"background\")\n        finally:\n            BACKGROUND_ONLY.reset(token)\n\n    def test_dr02_no_reissue_when_wants_foreground_false(self):\n        # A refusal WITHOUT the foreground escalation marker must NOT trigger\n        # the re-issue even with the opt-in (it is not DR-02 eligible).\n        from autoskill.desktop.actions import BACKGROUND_ONLY\n        from autoskill.protocol import InteractiveRequired, ProtocolError\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        not_fg = self._err_w_predicates(\"some_other_code\", wants_fg=False)\n        token = BACKGROUND_ONLY.set(True)\n        try:\n            with patch(\"autoskill.desktop.driver_backend.try_call\",\n                       return_value=not_fg) as call:\n                with self.assertRaises(ProtocolError) as caught:\n                    actions.click(store, ref)\n            self.assertNotIsInstance(caught.exception, InteractiveRequired)\n            self.assertEqual(call.call_count, 1)\n        finally:\n            BACKGROUND_ONLY.reset(token)\n\n    def test_stale_ref_from_message_with_25202(self):\n        # D4: the -25202 needle from CUA's stale_element predicate.\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        stale_25202 = self._err_w_predicates(\n            \"some_unrelated_code\", stale_el=True,\n            message=\"UIA operation failed with error -25202\")\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=stale_25202):\n            with self.assertRaises(ProtocolError) as caught:\n                actions.click(store, ref)\n        self.assertEqual(caught.exception.error.code, ErrorCode.STALE_REF)\n\n    def test_no_stale_when_stale_element_false(self):\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        not_stale = self._err_w_predicates(\"stale_element_token\",\n                                           stale_el=False)\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=not_stale):\n            with self.assertRaises(ProtocolError) as caught:\n                actions.click(store, ref)\n        # Without the stale_element boolean, it is NOT a stale ref\n        self.assertNotEqual(caught.exception.error.code, ErrorCode.STALE_REF)\n\n\nclass TestRefusalCodesUnique(unittest.TestCase):\n    \"\"\"H3/F3: REFUSAL_CODES must have unique keys (no silent overrides).\"\"\"\n\n    def test_no_duplicate_keys(self):\n        import ast\n        from pathlib import Path\n        source = Path(\"src/autoskill/protocol.py\").read_text(encoding=\"utf-8\")\n        tree = ast.parse(source)\n        for node in ast.walk(tree):\n            if isinstance(node, ast.Dict) and node.keys:\n                first_key = node.keys[0]\n                if isinstance(first_key, ast.Constant) and \"background_\" in str(first_key.value):\n                    keys = [k.value for k in node.keys if isinstance(k, ast.Constant)]\n                    dupes = [k for k in keys if keys.count(k) > 1]\n                    self.assertEqual(dupes, [], f\"duplicate keys silently override: {dupes}\")\n                    return\n        self.fail(\"REFUSAL_CODES dict not found in protocol.py\")\n\n    def test_live_cua_message_passed_through(self):\n        \"\"\"The SDK's live message text flows unchanged into the refusal.\"\"\"\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        live_msg = \"Background delivery is not available for target window class 'Chrome_WidgetWin_1'\"\n        refusal = _err(\"background_unavailable\", message=live_msg)\n        refusal[\"error\"][\"wants_foreground\"] = False  # not DR-02 eligible\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=refusal):\n            with self.assertRaises(ProtocolError) as caught:\n                actions.click(store, ref)\n        # The live message must appear verbatim in the error\n        self.assertIn(live_msg, caught.exception.error.message)\n\n    def test_unregistered_driver_code_not_replaced(self):\n        \"\"\"An unregistered code from the driver keeps its own identity.\"\"\"\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        unregistered = _err(\"some_exotic_sdk_code\", message=\"exotic failure\")\n        unregistered[\"error\"][\"wants_foreground\"] = False\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=unregistered):\n            with self.assertRaises(ProtocolError) as caught:\n                actions.click(store, ref)\n        # The exotic code must appear, not background_needs_physical_input\n        self.assertIn(\"some_exotic_sdk_code\", caught.exception.error.message)\n        self.assertNotIn(\"background_needs_physical_input\",\n                         caught.exception.error.message)\n\n\nclass TestK4aFix5(unittest.TestCase):\n    \"\"\"K4: DR-02 path carries CUA's live message and preserves the code.\"\"\"\n\n    def setUp(self):\n        env = patch.dict(os.environ, {\"AUTOSKILL_DRIVER\": \"on\"})\n        env.start()\n        self.addCleanup(env.stop)\n\n    def test_dr02_live_message_as_reason(self):\n        from autoskill.desktop.actions import BACKGROUND_ONLY\n        from autoskill.protocol import InteractiveRequired\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        live_msg = \"Background delivery is not available for target window class 'Chrome_WidgetWin_1'\"\n        bg = {\"ok\": False, \"error\": {\"code\": \"background_unavailable\",\n                                      \"message\": live_msg,\n                                      \"effect_state\": \"none\",\n                                      \"wants_foreground\": True,\n                                      \"stale_element\": False}}\n        token = BACKGROUND_ONLY.set(True)\n        try:\n            with patch(\"autoskill.desktop.driver_backend.try_call\",\n                       return_value=bg):\n                with self.assertRaises(InteractiveRequired) as caught:\n                    actions.click(store, ref)\n            # The live CUA message must be the reason\n            self.assertIn(live_msg, caught.exception.error.message)\n            # The code must be preserved\n            self.assertEqual(caught.exception.code, \"background_unavailable\")\n        finally:\n            BACKGROUND_ONLY.reset(token)\n\n    def test_dr02_unregistered_driver_code_preserved(self):\n        from autoskill.desktop.actions import BACKGROUND_ONLY\n        from autoskill.protocol import InteractiveRequired, REFUSAL_CODES\n        # Use a code that is genuinely NOT in REFUSAL_CODES\n        probe_code = \"zz_unregistered_probe\"\n        self.assertNotIn(probe_code, REFUSAL_CODES)\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        exotic = {\"ok\": False, \"error\": {\"code\": probe_code,\n                                          \"message\": \"exotic SDK failure\",\n                                          \"effect_state\": \"none\",\n                                          \"wants_foreground\": True,\n                                          \"stale_element\": False}}\n        token = BACKGROUND_ONLY.set(True)\n        try:\n            with patch(\"autoskill.desktop.driver_backend.try_call\",\n                       return_value=exotic):\n                with self.assertRaises(InteractiveRequired) as caught:\n                    actions.click(store, ref)\n            # The exotic driver code must be preserved\n            self.assertEqual(caught.exception.code, probe_code)\n            self.assertNotEqual(caught.exception.code, \"background_needs_physical_input\")\n            # delivery_refusal.reason is the live CUA message\n            dr = caught.exception.error.details[\"delivery_refusal\"]\n            self.assertEqual(dr[\"reason\"], \"exotic SDK failure\")\n        finally:\n            BACKGROUND_ONLY.reset(token)\n\n\nclass TestK2cReadback(unittest.TestCase):\n    \"\"\"K2c: confirmed+evidence is committed; fx10: no reply is followed by a\n    window walk (CUA makes none, impl_.rs:6188-6189, :5089-5109).\"\"\"\n\n    def setUp(self):\n        env = patch.dict(os.environ, {\"AUTOSKILL_DRIVER\": \"on\"})\n        env.start()\n        self.addCleanup(env.stop)\n\n    def test_confirmed_with_evidence_committed_no_walk(self):\n        store, ref = _token_ref()\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=_ok()) as call:\n            res = actions.set_value(store, ref, \"x\")\n        self.assertEqual(res[\"effect_state\"], \"committed\")\n        self.assertEqual(call.call_count, 1,\n                         \"no window_state walk after confirmed+evidence\")\n\n    def test_confirmed_without_evidence_does_not_walk(self):\n        # CUA demotes this shape at the seam; fx10: no walk follows it.\n        store, ref = _token_ref()\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   side_effect=[_ok(evidence=[])]) as call:\n            res = actions.set_value(store, ref, \"x\")\n        self.assertEqual(res[\"effect_state\"], \"unknown\", \"no caller upgrade\")\n        self.assertEqual(call.call_count, 1, \"no window_state walk\")\n\n    def test_unverifiable_does_not_walk(self):\n        store, ref = _token_ref()\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   side_effect=[_ok(effect=\"unverifiable\", verified=False)]) as call:\n            actions.set_value(store, ref, \"x\")\n        self.assertEqual(call.call_count, 1, \"no walk for unverifiable\")\n\n    def test_click_confirmed_committed(self):\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=_ok(evidence=[{\"kind\": \"window_change\",\n                                               \"detail\": \"menu closed\"}])):\n            res = actions.click(store, ref)\n        self.assertEqual(res[\"effect_state\"], \"committed\")\n\n\nclass TestK2dTimeout(unittest.TestCase):\n    \"\"\"K2d: driver_timeout has effect_state unknown, never 'no input was sent'.\"\"\"\n\n    def setUp(self):\n        env = patch.dict(os.environ, {\"AUTOSKILL_DRIVER\": \"on\"})\n        env.start()\n        self.addCleanup(env.stop)\n\n    def test_driver_timeout_is_unknown_not_none(self):\n        store, ref = _token_ref(role=\"button\", name=\"OK\")\n        timeout = {\"ok\": False, \"error\": {\n            \"code\": \"driver_timeout\",\n            \"message\": \"SDK request deadline expired\",\n            \"effect_state\": \"unknown\",\n            \"wants_foreground\": False, \"stale_element\": False}}\n        with patch(\"autoskill.desktop.driver_backend.try_call\",\n                   return_value=timeout):\n            with self.assertRaises(ProtocolError) as caught:\n                actions.click(store, ref)\n        self.assertEqual(caught.exception.error.effect_state.value, \"unknown\")\n        self.assertNotIn(\"no input was sent\", caught.exception.error.message.lower())\n\n\nclass TestB12ObserveScreenshot(unittest.TestCase):\n    \"\"\"B12-2 (c): the observe screenshot opt-in. Default observes are\n    byte-identical (no include_screenshot, no capture key); opting in sends\n    include_screenshot (+ max_image_dimension only when given), stores the\n    capture, and adds the additive \"capture\" reply key.\"\"\"\n\n    def setUp(self):\n        env = patch.dict(os.environ, {\"AUTOSKILL_DRIVER\": \"on\"})\n        env.start()\n        self.addCleanup(env.stop)\n\n    @staticmethod\n    def _window():\n        rect = SimpleNamespace(left=0, top=0, right=100, bottom=50)\n        return SimpleNamespace(Name=\"App\", NativeWindowHandle=77,\n                               ProcessId=100, BoundingRectangle=rect)\n\n    @classmethod\n    def _plain_reply(cls):\n        return {\"ok\": True, \"result\": {\n            \"elements\": [{\"element_index\": 1, \"element_token\": \"s00000060:1\",\n                          \"role\": \"Edit\", \"label\": \"t1\", \"depth\": 1}],\n            \"total_element_count\": 1, \"returned_element_count\": 1,\n            \"snapshot_id\": \"s00000060\"}}\n\n    @classmethod\n    def _shot_reply(cls):\n        reply = cls._plain_reply()\n        reply[\"result\"].update({\n            \"capture_id\": \"capture_\" + \"0\" * 32 + \"_1\",\n            \"screenshot_width\": 1568, \"screenshot_height\": 882,\n            \"screenshot_mime_type\": \"image/png\",\n            \"window_bounds\": {\"x\": 0, \"y\": 0, \"width\": 1920, \"height\": 1080},\n            \"images\": [{\"mime_type\": \"image/png\",\n                        \"data_base64\": \"iVBORw0KGgoAAAANS\"}]})\n        return reply\n\n    def _observe(self, p, reply):\n        from autoskill import handlers\n        session = SimpleNamespace(ref_store=RefStore(), id=\"sess-b12\")\n        with patch.object(handlers, \"_resolve_window\",\n                          return_value=self._window()), \\\n                patch(\"autoskill.desktop.driver_backend.try_call\",\n                      return_value=reply) as call, \\\n                patch.object(actions, \"_process_name\", return_value=\"app.exe\"), \\\n                patch.object(handlers, \"_appmem_note\", return_value=None), \\\n                patch.object(uia, \"observe\",\n                             side_effect=AssertionError(\"python walk used\")):\n            result = handlers._observe(SimpleNamespace(), session, p)\n        return result, session, call\n\n    def test_default_observe_takes_a_screenshot_like_cua(self):            # b12t7\n        \"\"\"b12t7 (OQ-B1 -> CUA's default, impl_.rs:1257): the default observe\n        sends include_screenshot; a reply with no capture surfaces CUA's\n        screenshot_error shape instead of an old stored capture.\"\"\"\n        from autoskill.desktop import captures\n        captures.clear()\n        self.addCleanup(captures.clear)\n        result, _, call = self._observe({\"max_nodes\": 100}, self._plain_reply())\n        self.assertEqual(call.call_args_list[0][0][0], \"window_state\")\n        self.assertEqual(call.call_args_list[0][0][1],\n                         {\"pid\": 100, \"window_id\": 77, \"max_elements\": 100,\n                          \"max_depth\": 25, \"include_screenshot\": True})\n        self.assertNotIn(\"capture\", result)\n        self.assertEqual(result[\"screenshot_error\"], \"the reply carried no capture_id\")\n\n    def test_explicit_false_is_the_tree_only_path(self):                   # b12t7\n        \"\"\"screenshot:false = CUA's \"cheap path for re-indexing\": the old\n        tree-only request and reply keys, byte-identical.\"\"\"\n        result, _, call = self._observe({\"screenshot\": False, \"max_nodes\": 100},\n                                        self._plain_reply())\n        self.assertEqual(call.call_args_list[0][0][1],\n                         {\"pid\": 100, \"window_id\": 77,\n                          \"max_elements\": 100, \"max_depth\": 25})\n        self.assertEqual(set(result), {\"text\", \"app\", \"window_title\",\n            \"window_rect\", \"ref_count\", \"node_count\", \"truncated\",\n            \"truncation_reason\", \"modal\", \"elapsed_ms\", \"effect_state\"})\n\n    def test_stale_stored_capture_is_never_shown_as_this_observes(self):   # b12t7\n        from autoskill.desktop import captures\n        captures.clear()\n        self.addCleanup(captures.clear)\n        self._observe({\"max_nodes\": 100}, self._shot_reply())        # stores one\n        result, _, _ = self._observe({\"max_nodes\": 100}, self._plain_reply())\n        self.assertNotIn(\"capture\", result)\n        self.assertIn(\"screenshot_error\", result)\n\n    def test_implicit_default_refusal_fails_open_like_before(self):        # b12t7\n        from autoskill import handlers\n        session = SimpleNamespace(ref_store=RefStore(), id=\"sess-b12\")\n        reply = _err(\"driver_error\", state=\"none\", message=\"busy\")\n        with patch(\"autoskill.desktop.driver_backend.try_call\", return_value=reply), \\\n                patch.object(uia, \"observe\", return_value=\"PYTHON-WALK\"):\n            got = handlers._observe_via_driver_or_python(\n                self._window(), session, proc=\"app.exe\", title=\"App\",\n                include_offscreen=False, max_nodes=100, max_depth=25,\n                screenshot=True, screenshot_explicit=False)\n        self.assertEqual(got, \"PYTHON-WALK\")\n\n    def test_screenshot_opt_in_sends_include_screenshot_and_stores(self):   # RED\n        from autoskill.desktop import captures\n        captures.clear()\n        self.addCleanup(captures.clear)\n        result, _, call = self._observe({\"screenshot\": True, \"max_nodes\": 100},\n                                        self._shot_reply())\n        self.assertEqual(call.call_args_list[0][0][1],\n                         {\"pid\": 100, \"window_id\": 77, \"max_elements\": 100,\n                          \"max_depth\": 25, \"include_screenshot\": True})\n        self.assertEqual(result[\"capture\"], {\n            \"capture_id\": \"capture_\" + \"0\" * 32 + \"_1\",\n            \"mime_type\": \"image/png\", \"width\": 1568, \"height\": 882,\n            \"image_base64\": \"iVBORw0KGgoAAAANS\"})\n        entry = captures.peek(\"sess-b12\", 100, 77)   # held after the observe\n        self.assertIsNotNone(entry)\n        self.assertEqual(entry.window_bounds,\n                         {\"x\": 0, \"y\": 0, \"width\": 1920, \"height\": 1080})\n        # HEAD red: p[\"screenshot\"] ignored -> no include_screenshot, no key.\n        # fx2 (t1 I2/I7): the delivered image size is the window's pixel\n        # space for a later --relative click.\n        self.assertEqual(captures.image_size(77), (1568, 882))\n\n    def test_max_image_dimension_forwards_only_when_given(self):            # RED\n        for p, extra in (({\"screenshot\": True, \"max_nodes\": 100,\n                           \"max_image_dimension\": 640},\n                          {\"max_image_dimension\": 640}),\n                         ({\"screenshot\": True, \"max_nodes\": 100}, {})):\n            with self.subTest(p=p):\n                _, _, call = self._observe(dict(p), self._shot_reply())\n                self.assertEqual(call.call_args_list[0][0][1],\n                                 {\"pid\": 100, \"window_id\": 77,\n                                  \"max_elements\": 100, \"max_depth\": 25,\n                                  \"include_screenshot\": True, **extra})\n        # absent -> NOT sent: the adapter's H7 1568 applies (b12t1).\n\n    def test_opt_in_changes_only_the_capture_key(self):                     # RED\n        # b12t7: the tree-only baseline is now the explicit screenshot:false.\n        default, _, _ = self._observe({\"screenshot\": False, \"max_nodes\": 100},\n                                      self._plain_reply())\n        opted, _, _ = self._observe({\"screenshot\": True, \"max_nodes\": 100},\n                                     self._shot_reply())\n        self.assertEqual(set(opted), set(default) | {\"capture\"})\n        for key in default:\n            if key != \"elapsed_ms\":\n                self.assertEqual(opted[key], default[key])\n\n    def test_screenshot_refusal_surfaces_verbatim_and_stores_nothing(self): # RED\n        from autoskill.desktop import captures\n        captures.clear()\n        self.addCleanup(captures.clear)\n        reply = _err(\"capture_too_large\", state=\"none\", message=(\n            \"Window capture publication failed: the capture registry is full\"))\n        with self.assertRaises(ProtocolError) as caught:\n            self._observe({\"screenshot\": True, \"max_nodes\": 100}, reply)\n        self.assertIn(\"capture_too_large\", caught.exception.error.message)\n        self.assertIn(\"Window capture publication failed\",\n                      caught.exception.error.message)\n        self.assertEqual(caught.exception.error.effect_state.value, \"none\")\n        self.assertIsNone(captures.peek(\"sess-b12\", 100, 77))\n        # HEAD red: the error reply fails open to the patched python walk ->\n        # AssertionError, not ProtocolError; the code never surfaces.\n\n    def test_toolspec_exposes_the_opt_in(self):                             # RED (optional row, rule 0.0 toolspec MUST CHANGE)\n        from autoskill import toolspec\n        entry = next(e for e in toolspec.TOOLS\n                     if e[\"name\"] == \"observe_window\")\n        self.assertIn(\"screenshot\", entry[\"schema\"][\"properties\"])\n        self.assertIn(\"max_image_dimension\", entry[\"schema\"][\"properties\"])\n");
